const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.7071068,0,0,0.7071068],down:[0.7071068,0,0,0.7071068],left:[0,0,0.7071068,0.7071068],right:[0,0,-0.7071068,0.7071068]};
const dist=s=>(2-s.c)+(2-s.r);
export function initialState(){return {c:0,r:0,moves:0,hint:null,msg:'Reach the gold goal square.'};}
export function reduce({state,event}){
 if(event.type!=='action')return state;
 const s={...state};
 const won=s.c===2&&s.r===2;
 if(event.action==='hintA'){
  if(won){s.msg='Already at the goal. Press Reset to play again.';return s;}
  s.hint=s.c<2?'right':'up';s.msg='Hint: move '+s.hint[0].toUpperCase()+s.hint.slice(1)+'.';return s;
 }
 const d=D[event.action];if(!d)return state;
 if(won){s.msg='You already won. Press Reset to play again.';return s;}
 const c=s.c+d[0],r=s.r+d[1];
 if(c<0||c>2||r<0||r>2){s.msg='That move would leave the board.';s.hint=null;return s;}
 s.c=c;s.r=r;s.moves++;s.hint=null;
 s.msg=dist(s)===0?'You reached the goal in '+s.moves+' moves (shortest: 4).':'Moved '+event.action+'.';
 return s;
}
export function evaluate({state}){
 const s=state||initialState();
 const x=(s.c-1)*1.1,z=(1-s.r)*1.1,won=s.c===2&&s.r===2;
 const n={token:{position:[x,won?0.48:0.4,z]},hint:{visible:false}};
 if(s.hint){const d=D[s.hint];n.hint={visible:true,position:[x+d[0]*0.32,0.4,z-d[1]*0.32],quaternion:Q[s.hint]};}
 return {nodes:n,readouts:{moves:s.moves,steps:dist(s)},goal:{status:won?'won':'playing',message:s.msg}};
}
